CREATE POLICY "Admins can read guest images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'guests' AND has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins can upload guest images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'guests' AND has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins can update guest images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'guests' AND has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (bucket_id = 'guests' AND has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins can delete guest images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'guests' AND has_role(auth.uid(), 'admin'::app_role));